  static String phaseForEvent(String event) {
    switch(event) {
      case "pttDown": return "listening";
      case "pttUp": return "recognizing";
      case "recognitionDone": return "thinking";
      case "search": return "searching";
      case "synthesis": return "synthesizing";
      case "reply": return "speaking";
      case "playbackDone": return "finished";
      case "shortInput": return "tooShort";
      case "emptyInput": return "nospeech";
      case "failure": return "error";
      case "reset": return "idle";
      case "newConversation": return "idle";
      default: throw new IllegalArgumentException("Unknown UI event: "+event);
    }
  }
  static String label(String id) {
    switch(id) {
      case "idle": return T_PHASE_IDLE;
      case "listening": return T_PHASE_LISTENING;
      case "recognizing": return T_PHASE_RECOGNIZING;
      case "thinking": return T_PHASE_THINKING;
      case "searching": return T_PHASE_SEARCHING;
      case "synthesizing": return T_PHASE_SYNTHESIZING;
      case "speaking": return T_PHASE_SPEAKING;
      case "finished": return T_PHASE_FINISHED;
      case "error": return T_PHASE_ERROR;
      case "nospeech": return T_PHASE_NOSPEECH;
      case "tooShort": return T_PHASE_TOOSHORT;
      case "unconfigured": return T_PHASE_UNCONFIGURED;
      case "recordCheck": return T_PHASE_RECORDCHECK;
      case "playbackCheck": return T_PHASE_PLAYBACKCHECK;
      case "checkDone": return T_PHASE_CHECKDONE;
      case "checkFailed": return T_PHASE_CHECKFAILED;
      case "clearFailed": return T_PHASE_CLEARFAILED;
      case "busy": return T_PHASE_BUSY;
      default: throw new IllegalArgumentException("Unknown UI state: "+id);
    }
  }
  static int stage(String label) {
    if(label.equals(T_PHASE_LISTENING))return 1;
    if(label.equals(T_PHASE_RECOGNIZING))return 2;
    if(label.equals(T_PHASE_THINKING))return 3;
    if(label.equals(T_PHASE_SEARCHING))return 3;
    if(label.equals(T_PHASE_SYNTHESIZING))return 4;
    if(label.equals(T_PHASE_RECORDCHECK))return 1;
    return 0;
  }
